var MEDIAver = 1.07;
function SetMedia(id,treeNumber,index){//id - id elementu, treeNumber - číslo knihovny, index - index ikony, type - 1 (true) = normální ikona, type - 0 (fALSE) - zobrazení metro ikon
	try{
		var el = document.getElementById(id);
		if (el.tagName.toLowerCase() == "audio")
			el.src = eval("MediaTree"+treeNumber+".ListData["+index+"];");
	}catch(erd){
		return undefined;
	}
}

function MediaPlay(id){
	try{
		var el = document.getElementById(id);
		el.load();
		var waittimer = window.setInterval(function(){if (el.readyState == 4){el.play(); window.clearInterval(waittimer);}},300);
	}catch(erd){
		return undefined;
	}
}

